import {run,THREE,box,sphere,floor,ring,makeHero} from './lib/core.js';import {Soccer} from './rules.js';
run({title:'Boost Circuit',genre:'Arcade / car football',accent:'#82edd1',description:'Drive, boost and jump your way to goal. A physics-driven car football match against an AI opponent, with boost pads and sudden-death overtime.',controls:[['W / S','Accelerate / reverse'],['A / D','Steer'],['Shift','Boost'],['Space','Jump'],['C','Camera'],['P / Esc','Pause']],touch:[['KeyA','←'],['KeyD','→'],['KeyW','Drive'],['KeyS','Reverse'],['ShiftLeft','Boost'],['Space','Jump'],['KeyC','Camera']],options:[{id:'duration',label:'Match',values:[['standard','2 minute match'],['quick','1 minute sprint']]}],buildIntro:'An original small-stadium car football project inspired by arcade sports games.',build:[['Vehicle modelling','Created the chassis, cabin, spoiler, wheels and lights in Blender. Exported one original GLB and recoloured a second instance for the rival.'],['Car and ball physics','Integrated acceleration, steering, drag, jumping and boost. Sphere/car contacts transfer momentum; ground and wall bounces keep the ball in play.'],['Rules and opponent','Built goal detection, kickoffs, a match clock, first-to-five scoring and overtime. The AI steers toward a point behind the ball to attack.'],['Stadium presentation','Constructed a lit pitch, line markings, goal frames and boost pads in Three.js, with follow and tactical cameras.']]},(ctx,model)=>{const {scene,camera}=ctx;floor(scene,150,0x0b192b);box(scene,0,-.15,0,28,.25,40,0x204d4e);for(let i=-4;i<5;i++)box(scene,0,.003,i*4.4,27.8,.015,2.2,i%2?0x245957:0x1f5050);for(const x of [-14,14]){box(scene,x,1.5,0,.3,3,40,0x263653);box(scene,x,3.05,0,.15,.1,40,0x75e6de)}for(const z of [-20,20]){for(const x of [-9.5,9.5])box(scene,x,1.5,z,9,3,.3,0x263653);for(const x of [-5,5])box(scene,x,2,z,.2,4,.2,z<0?0x91b9ff:0xffb282);box(scene,0,4,z,10,.2,.2,z<0?0x91b9ff:0xffb282);for(let x=-5;x<=5;x++)box(scene,x,2,z+Math.sign(z)*1.8,.025,4,.025,0x71839a);for(let y=0;y<=4;y++)box(scene,0,y,z+Math.sign(z)*1.8,10,.025,.025,0x71839a)}
box(scene,0,.025,0,28,.03,.08,0x8aada6);ring(scene,0,.04,0,4,0x9bbcb6);const car=[makeHero(model,scene,.7),makeHero(model,scene,.7,0xf0a281)],flames=car.map(()=>sphere(scene,0,0,0,.32,0x74ffef)),ball=sphere(scene,0,1,0,1,0xf9f4e2);const seam=new THREE.Mesh(new THREE.TorusGeometry(1.005,.025,5,32),new THREE.MeshBasicMaterial({color:0x0f2e42}));ball.add(seam);const pads=[[-9,-12],[9,-12],[-9,12],[9,12]].map(([x,z])=>ring(scene,x,.05,z,1,0xe6ce87));let sim=new Soccer(),overhead=false,finished=false;camera.position.set(0,13,25);camera.lookAt(0,0,0);
return {reset(o){sim=new Soccer(o);finished=false;overhead=false;ctx.announce('Kickoff · first to five')},update(dt){sim.update(dt,ctx.keys,ctx.pressed);if(ctx.pressed.has('KeyC'))overhead=!overhead;sim.cars.forEach((c,i)=>{car[i].position.set(c.x,c.y,c.z);car[i].rotation.y=c.angle;flames[i].position.set(c.x-Math.sin(c.angle)*1.5,c.y+.35,c.z-Math.cos(c.angle)*1.5);flames[i].visible=c.boosting;flames[i].scale.setScalar(.7+Math.sin(ctx.time*35)*.25)});const b=sim.ball;ball.position.set(b.x,b.y,b.z);ball.rotation.x+=b.vz*dt;ball.rotation.z-=b.vx*dt;pads.forEach((p,i)=>p.visible=sim.padTimers[i]===0);
const p=sim.cars[0],pos=overhead?new THREE.Vector3(0,38,14):new THREE.Vector3(p.x-Math.sin(p.angle)*9,7.5,p.z-Math.cos(p.angle)*9);camera.position.lerp(pos,1-Math.exp(-dt*3.5));camera.lookAt(overhead?new THREE.Vector3(0,0,0):new THREE.Vector3(p.x+Math.sin(p.angle)*6,1,p.z+Math.cos(p.angle)*6));
ctx.hud(`<div><strong>YOU ${sim.score[0]} — ${sim.score[1]} RIVAL</strong><small>${sim.time===0?'SUDDEN DEATH':Math.floor(sim.time/60)+':'+String(Math.ceil(sim.time%60)).padStart(2,'0')} · FIRST TO FIVE</small></div><div><strong>${Math.round(Math.abs(p.speed)*6)} km/h</strong><small>BOOST ${Math.round(p.boost)} · ${overhead?'TACTICAL':'FOLLOW'} CAMERA</small><div class="meter"><i style="width:${p.boost}%"></i></div></div>`);for(const e of sim.events){if(e==='goal-player'){ctx.announce('GOAL! Beautiful finish.');ctx.tone(660,.3)}if(e==='goal-rival')ctx.announce('Rival scores · next kickoff');if(e==='kick')ctx.tone(160,.06);if(e==='boost')ctx.tone(440,.1)}if(sim.over&&!finished){finished=true;ctx.end(sim.winner===0?'That’s a win.':'One more match?',`You ${sim.score[0]} — ${sim.score[1]} Rival. Keep your car behind the ball and use boost pads to set up a shot.`)}},snapshot(){return {score:sim.score,time:sim.time,ball:{...sim.ball},over:sim.over}}};});
